create or replace package body t005_stock_util as
  function available(p_product_id in number) return number is
    l_on_hand number;
    l_reserved number;
  begin
    select on_hand, reserved
      into l_on_hand, l_reserved
      from t005_stock
     where product_id = p_product_id;
    return l_on_hand - l_reserved;
  exception
    when no_data_found then
      -- If product doesn't exist in stock table, it has 0 on hand and 0 reserved.
      return 0;
  end available;
end t005_stock_util;
/

create or replace package body t005_stock_util as
  function available(p_product_id in number) return number is
    l_available number;
  begin
    select on_hand - NVL(reserved, 0)
      into l_available
      from t005_stock
     where product_id = p_product_id;
    return l_available;
  exception
    when no_data_found then
      return 0;
  end available;
end t005_stock_util;
/
